  const inEvent=(row:Row)=>!pref.eventId||(table==='event_participations'?row.event_id===pref.eventId:marketingScope?marketingTargets(data,marketingScope,row,pref.eventId).length>0:true);
  const filterField=def.fields.find(field=>field.key===(table==='projects'?'status':table==='accounts'?'lead_status':table==='opportunities'?'stage':table==='intake_leads'?'journey_status':table==='vendor_costs'?'status':table==='events'?'event_type':table==='event_participations'?'participation_status':''));
  const filtered=rows.filter(row=>(pref.filter==='All'||!filterField||(pref.filter==='Open'? !['Won','Lost'].includes(row.stage):String(row[filterField.key])===pref.filter))&&inEvent(row)&&matchesSourceFilters(data,row,pref.filters,filterFields,readFilter,pref.filterMode,rules=>marketingScope?matchesMarketingFilters(data,marketingScope,row,rules,filterFields,readFilter,pref.filterMode,pref.eventId):matchesFilters(row,rules,filterFields,readFilter,pref.filterMode),pref.eventId)&&controlFields.some(field=>display(row,field,data,pref.eventId).toLocaleLowerCase().includes(search.toLocaleLowerCase())));
