  const columns=orderedFields.filter(field=>pref.visibleKeys.includes(field.key));
  const listField=groupOptions.find(field=>field.key===pref.listGroupBy);
  const listGroups:ListGroup[]=[];
  if(listField?.type==='multiselect'){listGroups.push(...membershipGroups(sorted,row=>tableValue(row,listField,data,pref.eventId) as string[],new Map((listField.relation?relationOptions(listField,{id:''},data):(listField.options||[]).map(value=>({value,label:value}))).map(option=>[option.value,option.label]))).sort((a,b)=>a.label.localeCompare(b.label,undefined,{numeric:true,sensitivity:'base'})));}
  else if(listField){const map=new Map<string,ListGroup>();const labels=listField.relation?new Map(relationOptions(listField,{id:''},data).map(option=>[option.value,option.label])):null;for(const row of sorted){const raw=tableValue(row,listField,data,pref.eventId);const key=Array.isArray(raw)?[...raw].sort().join(', '):listField.type==='date'?String(raw??'').slice(0,10):String(raw??'');const group:ListGroup=map.get(key)||{key,label:key===''?'Unassigned':labels?labels.get(key)||'Unassigned':display(row,listField,data,pref.eventId),rows:[]};group.rows.push(row);map.set(key,group);}listGroups.push(...map.values());listGroups.sort((a,b)=>{const ai=listField.options?.indexOf(a.key)??-1,bi=listField.options?.indexOf(b.key)??-1;return ai!==bi&&(ai>=0||bi>=0)?(ai<0?Number.MAX_SAFE_INTEGER:ai)-(bi<0?Number.MAX_SAFE_INTEGER:bi):a.label.localeCompare(b.label,undefined,{numeric:true,sensitivity:'base'});});}
