  if(!groupField.required&&groupField.type!=='boolean')grouped.set('',[]);
  if(groupField?.options)groupField.options.filter(value=>!(table==='opportunities'&&pref.filter==='Open'&&['Won','Lost'].includes(value))&&(!filterField||filterField.key!==groupField.key||['All','Open'].includes(pref.filter)||pref.filter===value)).forEach(value=>grouped.set(value,[]));
  const groupValue=(row:Row)=>{const value=tableValue(row,groupField,data,pref.eventId);return value===null||value===undefined?'':String(value);};
