  if(groupField.type==='multiselect'&&groupField.registrationScope&&groupField.options){const memberships=new Map(grouped);grouped.clear();grouped.set('',memberships.get('')||[]);for(const option of groupField.options)grouped.set(option,memberships.get(option)||[]);for(const [key,items] of memberships)if(!grouped.has(key))grouped.set(key,items);}
